documentTemplateCSS:
@page{size:A4 portrait;margin:12mm}
.doc-a4{direction:rtl;box-sizing:border-box;width:186mm;min-height:273mm;margin:0 auto;padding:0;color:#242b31;background:#fff;font:14px/1.8 Tajawal,Cairo,Tahoma,Arial,sans-serif;display:flex;flex-direction:column}
.doc-a4 *{box-sizing:border-box}
.doc-header{display:grid;grid-template-columns:minmax(0,1fr) 24mm minmax(0,1fr);gap:5mm;align-items:center;border-bottom:1.5px solid #8c969f;padding:3mm 0 5mm;break-inside:avoid}
.doc-org{display:flex;flex-direction:column;font-size:12px;line-height:1.65}.doc-ministry-logo{width:24mm;max-height:24mm;object-fit:contain}
.doc-reference{margin:0;font-size:11px}.doc-reference>div{display:flex;gap:4px}.doc-reference dt{font-weight:700;white-space:nowrap}.doc-reference dt:after{content:":"}.doc-reference dd{margin:0;overflow-wrap:anywhere}
.doc-title{text-align:center;font-size:20px;line-height:1.6;margin:7mm 0 5mm;font-weight:700}
.doc-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3mm}
.doc-field{min-width:0;padding:3mm 4mm;border:1px solid #d2d7dc;border-radius:2mm;break-inside:avoid}
.doc-field-wide{grid-column:1/-1}.doc-field strong{display:block;font-size:13px;color:#48515a}.doc-field p{margin:1mm 0 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.9}
.doc-attachments,.doc-signatures{margin-top:7mm;break-inside:auto}.doc-attachments h2,.doc-signatures h2{font-size:15px;border-bottom:1px solid #c9cfd4;margin:0 0 3mm;padding-bottom:2mm;break-after:avoid}
.doc-attachment-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:3mm}.doc-attachment-list figure{margin:0;padding:2mm;border:1px solid #ddd;break-inside:avoid}.doc-attachment-list img{width:100%;max-height:43mm;object-fit:contain}.doc-attachment-list figcaption{font-size:11px;text-align:center;overflow-wrap:anywhere}.doc-pdf{text-align:center;padding:12mm 0;font-weight:bold}
.doc-signer-list{display:flex;gap:6mm;flex-wrap:wrap}.doc-signer{flex:1 1 55mm;display:flex;flex-direction:column;min-height:23mm;break-inside:avoid}.doc-signer strong{font-size:14px}.doc-signer img{max-width:55mm;max-height:20mm;object-fit:contain;object-position:right}
.doc-footer{margin-top:auto;border-top:1px solid #cbd1d6;padding-top:3mm;display:flex;align-items:center;gap:4mm;font-size:10px;color:#606b75;break-inside:avoid}.doc-footer img{height:9mm;max-width:25mm;object-fit:contain}.doc-footer time{margin-right:auto}
.doc-page-current:after{content:counter(page)}.doc-page-total:after{content:counter(pages)}
@media screen{.doc-a4{box-shadow:0 2px 14px #0002;padding:10mm;min-height:297mm;width:210mm}}
@media print{html,body{margin:0!important;padding:0!important;overflow:visible!important;background:#fff!important}.doc-a4{width:186mm;min-height:273mm;box-shadow:none!important;padding:0!important}.doc-field,.doc-attachment-list figure,.doc-signer{break-inside:avoid}.doc-field-wide{break-inside:auto}.doc-footer{break-inside:avoid}button,.doc-no-print{display:none!important}}

officialDocumentStyle:
/* Unified print-only design system. Keep all dimensions within the A4 printable area. */
@page{size:A4 portrait;margin:12mm}
.doc-a4{width:186mm;min-height:273mm;font-family:Tajawal,Cairo,Tahoma,Arial,sans-serif;color:#26323d;font-size:14px;line-height:1.8}
.doc-header{grid-template-columns:minmax(0,1fr) 26mm minmax(0,1fr);gap:4mm;align-items:center;padding:2mm 0 4mm;border-bottom:1.2px solid #7c8790}
.doc-org{font-size:12px;line-height:1.65}.doc-org strong:last-child{font-size:13px}
.doc-ministry-logo{width:26mm;max-height:25mm}
.doc-reference{border:1px solid #d5dbe0;border-radius:2mm;font-size:11px;overflow:hidden}
.doc-reference>div{display:grid;grid-template-columns:45% 55%;gap:0;border-bottom:1px solid #d5dbe0;align-items:center}
.doc-reference>div:last-child{border-bottom:0}
.doc-reference dt,.doc-reference dd{padding:1mm 2mm}
.doc-reference dt{background:#eef1f4}.doc-reference dt:after{content:""}
.doc-title{background:#526878;color:#fff;border-left:3px solid #e9903c;border-right:3px solid #e9903c;border-radius:2mm;padding:2.2mm 3mm;font-size:19px;line-height:1.55;margin:5mm 0 4mm;print-color-adjust:exact;-webkit-print-color-adjust:exact}
.doc-fields{gap:0;border-top:1px solid #cbd2d9;border-right:1px solid #cbd2d9}
.doc-field{border:0;border-bottom:1px solid #cbd2d9;border-left:1px solid #cbd2d9;border-radius:0;min-height:16mm;padding:2mm 3mm}
.doc-field strong{font-size:12px;line-height:1.5;padding:1mm 2mm;margin:-2mm -3mm 2mm;background:#edf1f4;color:#303b46;print-color-adjust:exact;-webkit-print-color-adjust:exact}
.doc-field p{font-size:14px;line-height:1.8;margin:1mm 0 0}
.doc-field-wide{min-height:18mm}
.doc-attachments,.doc-signatures{margin-top:5mm}
.doc-attachments h2,.doc-signatures h2{background:#e9eef2;border-right:3px solid #e9903c;padding:2mm 3mm;margin:0 0 3mm;font-size:14px;print-color-adjust:exact;-webkit-print-color-adjust:exact}
.doc-attachment-list{gap:2mm}
.doc-attachment-list figure{border:1px solid #d7dfe5;border-radius:1mm;padding:2mm}
.doc-attachment-list img{max-height:40mm}
.doc-signer-list{gap:4mm}.doc-signer{min-height:22mm;border:1px solid #d7dfe5;padding:2mm;flex-basis:65mm}
.doc-signer strong{font-size:13px;background:#f6eee7;padding:1mm 2mm;margin:-2mm -2mm 2mm;print-color-adjust:exact}
.doc-signer span{font-size:12px}
.doc-footer{font-size:10px;border-top:1px solid #b7c0c8;padding-top:2mm;gap:3mm}
.doc-footer img{height:8mm;max-width:23mm}
.doc-page-counter{white-space:nowrap}
@media screen{.doc-a4{width:210mm;min-height:297mm;padding:12mm;box-shadow:0 2px 16px #0002}}
@media print{
html,body{overflow:visible!important}
.doc-a4{width:186mm!important;min-height:0!important;padding:0!important;box-shadow:none!important;display:block!important}
.doc-header,.doc-title,.doc-signatures h2,.doc-attachments h2{break-inside:avoid;break-after:avoid}
.doc-fields{display:block!important;border:0!important}
.doc-fields:after{content:"";display:block;clear:both}
.doc-field{display:block;float:none!important;clear:both;width:100%;min-height:0;border:1px solid #cbd2d9;margin:0 0 -1px;break-inside:avoid}
.doc-field-wide{float:none;clear:both;width:100%;min-height:0;break-inside:auto}
.doc-attachments,.doc-signatures{clear:both}
.doc-footer{clear:both;margin-top:6mm;break-inside:avoid;page-break-inside:avoid}
}

/* Center every official authority line within the right header column. */
.doc-header .doc-org{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;font-size:12px;line-height:1.75;min-width:0}
.doc-header .doc-org span,.doc-header .doc-org strong{display:block;width:100%;text-align:center;overflow-wrap:anywhere}
.doc-header .doc-org strong:last-child{font-size:13px;font-weight:700}

/* ATHAT approved report identity: neutral grey, warm orange, white A4. */
.doc-a4.doc-report{--report-ink:#36383b;--report-accent:#c05a1a;--report-paper:#fff;--report-soft:#f4f4f4;color:var(--report-ink);background:var(--report-paper)}
.doc-report .doc-header{background:#36383b;color:#fff;border-bottom:3px solid #c05a1a;border-radius:2mm;padding:4mm;grid-template-columns:minmax(0,1fr) 23mm minmax(0,1fr)}
.doc-report .doc-org,.doc-report .doc-org span,.doc-report .doc-org strong{color:#fff!important}
.doc-report .doc-reference{border:1px solid #73777b;background:#46484b;color:#fff}
.doc-report .doc-reference>div{border-bottom-color:#73777b}
.doc-report .doc-reference dt{background:#56585a;color:#fff}
.doc-report .doc-reference dd{color:#fff}
.doc-report .doc-ministry-logo{object-fit:contain;background:#fff;border-radius:2mm;padding:1mm}
.doc-report .doc-title{background:#f4f4f4;color:#36383b;border:0;border-right:4px solid #c05a1a;border-radius:2mm;padding:4mm;text-align:center;font-weight:800;font-size:21px}
.doc-report .doc-fields{border:0;gap:3mm}
.doc-report .doc-field{border:1px solid #dedede;border-radius:2mm;background:#fff;overflow:hidden}
.doc-report .doc-field strong{background:#f1f1f1;color:#36383b;border-right:3px solid #c05a1a;padding:2mm 3mm;margin:-2mm -3mm 2mm;font-size:12px}
.doc-report .doc-field p{color:#383838}
.doc-report .doc-attachments h2,.doc-report .doc-signatures h2{background:#f4f4f4;color:#36383b;border-right:4px solid #c05a1a;border-radius:1mm}
.doc-report .doc-attachment-list figure,.doc-report .doc-signer{border-color:#dedede;border-radius:2mm}
.doc-report .doc-signer strong{background:#fff0e5;color:#834014}
.doc-report .doc-footer{border-top:2px solid #c05a1a;color:#555}
.doc-report .doc-footer img{object-fit:contain}
@media print{.doc-report .doc-fields{display:block!important}.doc-report .doc-field{margin-bottom:2mm;break-inside:avoid}.doc-report .doc-header,.doc-report .doc-title{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
